    fn new_capacity(queued: usize) -> Arc<QueryNetworkCapacity> {
        QueryNetworkCapacity::new(NetworkLimits {
            query_running: 1,
            query_queued: queued,
            background_running: 1,
            background_queued: 0,
        })
        .unwrap()
    }
    fn inputs(
