    ) -> QueryEncodingInputs {
        QueryEncodingInputs {
            cache,
            namespace: cc_semantic::cache::namespace_key("synthetic/query-service-test").unwrap(),
            spec: QueryEncodingSpec::new(
                provider.space().clone(),
                None,
                8192,
